<!-- 
 This page serves as a redirect to have a static link for a task notification email to the document. 
 It is not supposed to show anyhting and just redirects to the correct document status view or the 
 dashboard on an error while displaying an error message.

 On mount of this page we query the dashboard api for the document id and if we get a valid return
 it is the data needed to simulate the opening from the dashboard view. With the exception of not needing 
 to highlight/save the opened row. 

 I tried adding it as a utility and in src/router/routes.ts directly but did not manage to create a 
 working solution with those approaches.
 -->

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent } from 'vue';
import DashboardHelper from 'src/pages/Dashboard/DashboardHelper';
import { useUserStore } from 'src/store/main';
import type { dynamicObj } from 'src/pages/assets';
import { documentListApiService } from 'src/services';
import { useDocAttributesStore } from 'src/store/main';
export default defineComponent({
  components: {},
  mixins: [DashboardHelper],
  async mounted() {
    this.doc_id = this.$route.params.id.toString();
    if (await this.getDocumentInfos()) {
      // valid data for document, simulate opening from dashboard
      this.changeDocumentView();
    } else {
      // on error or no document data (wrong id, deleted...) redirect to dashboard
      this.$router.push('/dashboard');
    }
  },

  setup() {
    const doc_id = '';
    const user_store = useUserStore();
    const { isMediUser } = user_store;
    const row = {} as dynamicObj;
    return {
      row,
      doc_id,
      isMediUser,
    };
  },
  el: '#app',

  methods: {
    async getDocumentInfos() {
      let success = false;
      try {
        const query = '?document_ids=' + this.doc_id;
        const res = await documentListApiService.getList(query);
        success = true
          ? res['documents'] && res['documents'].length > 0
          : false;
        if (success) {
          this.row = res['documents'][0];
        } else {
          notify.error(this.$t('messages_DOCUMENT_NOT_FOUND'));
        }
        return success;
      } catch (err: any) {
        logError(err.message);
        notify.error(
          this.$t('ERROR_FETCHING_LINKED_DOCUMENT'),
        );
        return false;
      }
    },
    async changeDocumentView() {
      const doc_attribute_store = useDocAttributesStore();
      await doc_attribute_store.getDocTypeAllSettings();
      this.rowClick(this.row, false, this.isMediUser());
    },
  },
});
</script>
